    "price.eyebrow":"05 · Preise",
    "price.h2":"Du bezahlst für die Antworten,\nnicht für die Software.",
    "price.lede":"Jeder Plan kauft dir KI-Chart-Analysen — in Punkten bepreist, <b>ca. 300 Punkte pro Analyse</b>. Terminal, Indikatoren, Workspace und Non-custodial-Architektur sind in jedem Plan gleich. Du zahlst nur dafür, wie oft du fragst.",
    "price.per":"/Mon","price.analyses":"KI-Analysen / Monat","price.points":"Punkte",
    "price.cta_free":"Kostenlos starten","price.cta_paid":"{name} wählen",
    "price.p1_name":"Free","price.p1_h":"Erster Geschmack","price.p1_price":"$0","price.p1_analyses":"~3","price.p1_points":"1,000",
    "price.p1_l1":"Volle KI-Reads auf jedem gelisteten Paar","price.p1_l2":"Indikatoren, Zeichnungen, 24-Spalten-Workspace","price.p1_l3":"Non-custodial — deine Schlüssel, dein Konto","price.p1_l4":"Keine Karte, keine Einzahlung",
    "price.p2_name":"Basic","price.p2_h":"Ein paar Reads pro Tag","price.p2_price":"$19","price.p2_analyses":"~30","price.p2_points":"9,000",
    "price.p2_l1":"Alles aus Free","price.p2_l2":"Signal-Audit-Trail (These + Evidenz)","price.p2_l3":"Anfänger- und Pro-Erklärmodi","price.p2_l4":"E-Mail-Support",
    "price.p3_name":"Pro","price.p3_badge":"Bester Wert","price.p3_h":"Aktive Trader","price.p3_price":"$49","price.p3_analyses":"~100","price.p3_points":"30,000",
